//! File icon themes: which Catppuccin icon a file or folder name gets, and
//! the icon's colors in the flavor that matches the theme.
//!
//! The bundled icons are the Mocha flavor of Catppuccin's VS Code icons
//! (`scripts/vendor-catppuccin-icons.py`); the other flavors are derived by
//! swapping the palette, which reproduces the official icons exactly.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

/// The bundled icons and their name tables, generated by `scripts/vendor-catppuccin-icons.py`.
const BUNDLE: &str = include_str!("../../icons/catppuccin-icons.json");

/// Catppuccin's palette: each Mocha color and its Latte, Frappé and
/// Macchiato counterparts.
const PALETTE: [(&str, &str, &str, &str); 26] = [
    ("f5e0dc", "dc8a78", "f2d5cf", "f4dbd6"), // rosewater
    ("f2cdcd", "dd7878", "eebebe", "f0c6c6"), // flamingo
    ("f5c2e7", "ea76cb", "f4b8e4", "f5bde6"), // pink
    ("cba6f7", "8839ef", "ca9ee6", "c6a0f6"), // mauve
    ("f38ba8", "d20f39", "e78284", "ed8796"), // red
    ("eba0ac", "e64553", "ea999c", "ee99a0"), // maroon
    ("fab387", "fe640b", "ef9f76", "f5a97f"), // peach
    ("f9e2af", "df8e1d", "e5c890", "eed49f"), // yellow
    ("a6e3a1", "40a02b", "a6d189", "a6da95"), // green
    ("94e2d5", "179299", "81c8be", "8bd5ca"), // teal
    ("89dceb", "04a5e5", "99d1db", "91d7e3"), // sky
    ("74c7ec", "209fb5", "85c1dc", "7dc4e4"), // sapphire
    ("89b4fa", "1e66f5", "8caaee", "8aadf4"), // blue
    ("b4befe", "7287fd", "babbf1", "b7bdf8"), // lavender
    ("cdd6f4", "4c4f69", "c6d0f5", "cad3f5"), // text
    ("bac2de", "5c5f77", "b5bfe2", "b8c0e0"), // subtext1
    ("a6adc8", "6c6f85", "a5adce", "a5adcb"), // subtext0
    ("9399b2", "7c7f93", "949cbb", "939ab7"), // overlay2
    ("7f849c", "8c8fa1", "838ba7", "8087a2"), // overlay1
    ("6c7086", "9ca0b0", "737994", "6e738d"), // overlay0
    ("585b70", "acb0be", "626880", "5b6078"), // surface2
    ("45475a", "bcc0cc", "51576d", "494d64"), // surface1
    ("313244", "ccd0da", "414559", "363a4f"), // surface0
    ("1e1e2e", "eff1f5", "303446", "24273a"), // base
    ("181825", "e6e9ef", "292c3c", "1e2030"), // mantle
    ("11111b", "dce0e8", "232634", "181926"), // crust
];

/// A Catppuccin flavor the icons are drawn in.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Flavor {
    /// The light flavor.
    Latte,
    /// The lightest dark flavor.
    Frappe,
    /// The middle dark flavor.
    Macchiato,
    /// The darkest flavor, the one the icons are bundled in.
    Mocha,
}

impl Flavor {
    /// An icon in this flavor: every Mocha palette color (`#rrggbb`, any
    /// case) becomes its counterpart in this flavor; other colors stay.
    pub fn recolor(self, svg: &str) -> String {
        if self == Flavor::Mocha {
            return svg.to_owned();
        }
        let mut out = String::with_capacity(svg.len());
        let mut rest = svg;
        while let Some((before, after)) = rest.split_once('#') {
            out.push_str(before);
            out.push('#');
            let swapped = after
                .get(..6)
                .filter(|hex| {
                    hex.chars().all(|digit| digit.is_ascii_hexdigit())
                })
                .and_then(|hex| {
                    let hex = hex.to_ascii_lowercase();
                    PALETTE.iter().find(|row| row.0 == hex).map(
                        |&(mocha, latte, frappe, macchiato)| match self {
                            Flavor::Latte => latte,
                            Flavor::Frappe => frappe,
                            Flavor::Macchiato => macchiato,
                            Flavor::Mocha => mocha,
                        },
                    )
                });
            match swapped {
                Some(color) => {
                    out.push_str(color);
                    rest = after.get(6..).unwrap_or_default();
                }
                None => rest = after,
            }
        }
        out.push_str(rest);
        out
    }
}

/// The bundled icons and the tables that pick one for a file or folder name.
#[derive(Debug, Default, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FileIconCatalog {
    /// Icon of files no table matches.
    file: String,
    /// Icon of closed folders no table matches.
    folder: String,
    /// Icon of open folders no table matches.
    folder_expanded: String,
    /// Icons by lowercase extension, compound ones (`d.ts`) included.
    file_extensions: HashMap<String, String>,
    /// Icons by lowercase file name.
    file_names: HashMap<String, String>,
    /// Icons of closed folders by lowercase name.
    folder_names: HashMap<String, String>,
    /// Icons of open folders by lowercase name.
    folder_names_expanded: HashMap<String, String>,
    /// SVG source of every icon, in the Mocha flavor.
    icons: HashMap<String, String>,
}

impl FileIconCatalog {
    /// The bundled catalog, parsed on first use.
    pub fn builtin() -> &'static Self {
        static CATALOG: OnceLock<FileIconCatalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            serde_json::from_str(BUNDLE).unwrap_or_else(|error| {
                // The bundle is generated and tested; this keeps the default icons if it is not.
                tracing::error!("bundled file icons are unreadable: {}", error);
                FileIconCatalog::default()
            })
        })
    }

    /// The icon of a file: by its whole name, then by its extensions from the
    /// longest compound one (`d.ts` before `ts`), else the generic file icon.
    pub fn file(&self, name: &str) -> &str {
        let name = name.to_lowercase();
        if let Some(icon) = self.file_names.get(&name) {
            return icon;
        }
        name.match_indices('.')
            .filter_map(|(dot, _)| name.get(dot + 1..))
            .filter(|extension| !extension.is_empty())
            .find_map(|extension| self.file_extensions.get(extension))
            .unwrap_or(&self.file)
    }

    /// The icon of a folder by its name, open or closed.
    pub fn folder(&self, name: &str, expanded: bool) -> &str {
        let name = name.to_lowercase();
        let (table, fallback) = if expanded {
            (&self.folder_names_expanded, &self.folder_expanded)
        } else {
            (&self.folder_names, &self.folder)
        };
        table.get(&name).unwrap_or(fallback)
    }

    /// The Mocha SVG source of an icon.
    pub fn svg(&self, icon: &str) -> Option<&str> {
        self.icons.get(icon).map(String::as_str)
    }
}
